class BowlingGame:
    """Keeps track of a game of bowling and computes its final score."""

    def __init__(self):
        self._frames = []  # completed frames, each a list of rolls
        self._current = []  # rolls of the frame in progress
        self._complete = False

    def roll(self, pins):
        if not isinstance(pins, int) or pins < 0 or pins > 10:
            raise Exception(
                "A roll cannot score negative or more than 10 points."
            )
        if self._complete:
            raise Exception("Cannot roll after the game already has ten frames.")

        if len(self._frames) < 9:
            self._roll_normal_frame(pins)
        else:
            self._roll_tenth_frame(pins)

    def _roll_normal_frame(self, pins):
        if len(self._current) == 1 and self._current[0] + pins > 10:
            raise Exception(
                "Two rolls in a frame cannot score more than 10 points."
            )
        self._current.append(pins)
        if sum(self._current) == 10:
            self._frames.append(self._current)
            self._current = []

    def _roll_tenth_frame(self, pins):
        first, second = (self._current + [0, 0])[:2]
        if len(self._current) == 1:
            if first < 10 and first + pins > 10:
                raise Exception(
                    "Two rolls in a frame cannot score more than 10 points."
                )
        elif len(self._current) == 2:
            if first == 10:
                if second < 10 and second + pins > 10:
                    raise Exception(
                        "Two bonus rolls after a strike in the last frame "
                        "cannot score more than 10 points unless the first "
                        "is a strike."
                    )
            # A spare or open frame has no further rolls, but those states
            # complete the game, so this branch is unreachable.
        self._current.append(pins)
        if self._tenth_frame_complete():
            self._frames.append(self._current)
            self._current = []
            self._complete = True

    def _tenth_frame_complete(self):
        rolls = self._current
        if len(rolls) == 2:
            return sum(rolls) < 10
        if len(rolls) == 3:
            return rolls[0] == 10 or sum(rolls[:2]) == 10
        return False

    def score(self):
        if not self._complete:
            raise Exception("Score cannot be taken until the end of the game.")
        rolls = [pin for frame in self._frames for pin in frame]
        total = 0
        i = 0
        for frame in range(10):
            if frame < 9:
                if rolls[i] == 10:
                    total += 10 + rolls[i + 1] + rolls[i + 2]
                    i += 1
                elif rolls[i] + rolls[i + 1] == 10:
                    total += 10 + rolls[i + 2]
                    i += 2
                else:
                    total += rolls[i] + rolls[i + 1]
                    i += 2
            else:
                total += sum(rolls[i:])
        return total
